import {test,expect,beforeEach} from 'bun:test';
import {approvalFlowOn,approvalTally,humanChangeOn,humanResponsibilities} from '../src/governance.js';
import {channelReadProblem} from '../src/channels.js';
const storage=new Map();globalThis.localStorage={getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v),removeItem:k=>storage.delete(k)};
const api=await import('../src/store.js');beforeEach(()=>api.reset());
const record=id=>api.read().resources.approvals.find(r=>r.id===id);
const rule=(s,id,extra={})=>({tenantId:s.activeTenant,id,revision:1,action:'configure',reason:'固定规则',humanIds:s.organization.members.slice(0,2).map(p=>p.id),roles:[],mode:'并行',strategy:'ALL',quorum:2,timeoutSeconds:3600,timeoutAction:'提醒并保持待处理',...extra});
const setup=(extra={})=>{const id=api.requestModelApproval('MD-02',1);api.governanceApprovalCommand(rule(api.read(),id,extra));return id;};
const vote=(id,participantId,choice='已批准',extra={})=>api.governanceApprovalCommand({tenantId:api.read().activeTenant,id,revision:record(id).revision,action:'vote',participantId,actorId:participantId,simulate:true,reason:'核对来源',choice,...extra});
const atomic=fn=>{const before=structuredClone(api.read());expect(fn).toThrow();expect(api.read()).toEqual(before);};
test('ALL ANY QUORUM finalize only through existing decision with exact threshold',()=>{for(const strategy of ['ALL','ANY','QUORUM']){api.reset();const id=setup({strategy}),[a,b]=record(id).orchestration.participants;atomic(()=>api.resourceCommand('approvals',id,'已批准','不可跳过'));vote(id,a);expect(approvalTally(record(id)).result).toBe(strategy==='ANY'?'已批准':null);if(strategy!=='ANY')vote(id,b);api.resourceCommand('approvals',id,'已批准','规则已达标');expect(record(id).decision.targetRevision).toBe(1);atomic(()=>vote(id,a));}});
test('rejection depends on remaining voters',()=>{for(const strategy of ['ALL','ANY','QUORUM']){api.reset();const id=setup({strategy}),[a,b]=record(id).orchestration.participants;vote(id,a,'已拒绝');expect(approvalTally(record(id)).result).toBe(strategy==='ANY'?null:'已拒绝');if(strategy==='ANY')vote(id,b,'已拒绝');api.resourceCommand('approvals',id,'已拒绝','无法达标');expect(record(id).status).toBe('已拒绝');}});
test('sequential duplicate stale tenant unauthorized and unmarked simulation votes reject atomically',()=>{const id=setup({mode:'顺序'}),[a,b]=record(id).orchestration.participants;atomic(()=>vote(id,b));atomic(()=>vote(id,a,'已批准',{tenantId:'foreign'}));atomic(()=>vote(id,a,'已批准',{actorId:'unknown'}));atomic(()=>vote(id,a,'已批准',{revision:1}));vote(id,a);atomic(()=>vote(id,a));atomic(()=>vote(id,b,'已批准',{simulate:false}));api.update(s=>s.role='executor');atomic(()=>vote(id,b));api.update(s=>{s.role='owner';s.organization.members.find(p=>p.id===b).disabledAt='now';});atomic(()=>vote(id,b));});
test('roles freeze resolved names and stale source blocks voting',()=>{const role=api.read().organization.projectRoles[0],id=setup({humanIds:[],roles:[role.role],projectId:role.projectId}),fixed=structuredClone(record(id).orchestration.participants);api.update(s=>s.organization.projectRoles=[]);expect(record(id).orchestration.participants).toEqual(fixed);api.update(s=>s.resources.models.find(m=>m.id==='MD-02').revision=2);atomic(()=>vote(id,fixed[0]));});
test('delegation, timeout, escalation and resume use frozen policy',()=>{const id=api.requestModelApproval('MD-02',1),s=structuredClone(api.read()),ids=s.organization.members.map(p=>p.id),input=rule(s,id,{humanIds:[ids[0]],timeoutSeconds:1,timeoutAction:'请求负责人升级',delegateId:ids[1],escalationId:ids[0]});approvalFlowOn(s,input,1000);const r=s.resources.approvals.find(r=>r.id===id);const cmd=(action,extra={},now=1500)=>approvalFlowOn(s,{...input,revision:r.revision,action,participantId:ids[0],actorId:ids[1],simulate:true,choice:'已批准',...extra},now);expect(()=>cmd('vote',{actorId:ids[2]||'missing'})).toThrow();expect(()=>cmd('vote',{},2000)).toThrow();cmd('timeout',{},2000);expect(()=>cmd('resume',{},2100)).toThrow();cmd('resume',{actorId:ids[0]},2100);cmd('vote',{},2200);expect(approvalTally(r).result).toBe('已批准');const fresh=structuredClone(api.read());approvalFlowOn(fresh,{...input,timeoutAction:'到期终止等待'},1000);approvalFlowOn(fresh,{...input,revision:2,action:'timeout'},2000);expect(approvalTally(fresh.resources.approvals.find(r=>r.id===id)).result).toBe('待补充');});
const ci=(s,p,extra={})=>({tenantId:s.activeTenant,memberId:p.id,reason:'接管及撤权',...extra});
test('offboard and transfer revoke access first; dynamic responsibilities must all be accepted; old facts stay',()=>{for(const kind of ['离职','调岗']){const s=structuredClone(api.read()),p={id:'H-change',name:'交接测试成员',kind:'Human'},node=s.organization.nodes[0];s.organization.members.push(p);s.work[0].owner=p.name;s.work[0].status='进行中';const old=structuredClone(s.work[0].history);const id=humanChangeOn(s,ci(s,p,{action:'begin',kind,targetNodeId:node.id})),c=s.organization.memberChanges.find(c=>c.id===id);expect(channelReadProblem(s,'team',p.id)).not.toBe('');expect(c.access.credentialRevokedAt).toBeTruthy();const cmd=(action,extra={})=>humanChangeOn(s,ci(s,p,{action,id,revision:c.revision,...extra}));expect(()=>cmd('complete')).toThrow();let row=humanResponsibilities(s,p.id)[0];expect(()=>cmd('handoff',{key:row.key,expectedValue:'stale',successorId:'H-lin',confirmed:true})).toThrow();expect(()=>cmd('handoff',{key:row.key,expectedValue:row.value,successorId:'H-lin',confirmed:false})).toThrow();while((row=humanResponsibilities(s,p.id)[0]))cmd('handoff',{key:row.key,expectedValue:row.value,successorId:'H-lin',confirmed:true});s.work[1].status='进行中';s.work[1].owner=p.name;expect(()=>cmd('complete')).toThrow();row=humanResponsibilities(s,p.id)[0];cmd('handoff',{key:row.key,expectedValue:row.value,successorId:'H-lin',confirmed:true});cmd('complete');expect(s.work[0].history.slice(0,old.length)).toEqual(old);expect(c.status).toBe('已完成');expect(s.organization.projectRoles.some(r=>r.memberId===p.id)).toBe(false);if(kind==='离职'){expect(p.status).toBe('已离职');expect(channelReadProblem(s,'team',p.id)).not.toBe('');}else{expect(p.disabledAt).toBeUndefined();expect(node.memberIds).toContain(p.id);}}});
test('lifecycle role tenant offline and self revocation reject atomically',()=>{const p=api.read().organization.members.find(p=>p.id!=='H-lin'),cmd=extra=>api.governanceHumanCommand(ci(api.read(),p,{action:'begin',kind:'离职',...extra}));atomic(()=>cmd({tenantId:'foreign'}));atomic(()=>cmd({memberId:'H-lin'}));api.update(s=>s.role='executor');atomic(()=>cmd());api.update(s=>{s.role='owner';s.offline=true;});atomic(()=>cmd());});

test('version-bound business responsibility cannot be silently rewritten by offboarding',()=>{const s=structuredClone(api.read()),p=s.organization.members.find(p=>p.id==='H-zhou');s.resources.goals.push({id:'G-bound',name:'已冻结目标',owner:p.name,status:'进行中',activeBaseline:{definition:{owner:p.name}}});const id=humanChangeOn(s,ci(s,p,{action:'begin',kind:'离职'})),c=s.organization.memberChanges.find(c=>c.id===id),row=humanResponsibilities(s,p.id).find(r=>r.id==='G-bound');expect(()=>humanChangeOn(s,ci(s,p,{action:'handoff',id,revision:c.revision,key:row.key,expectedValue:row.value,successorId:'H-lin',confirmed:true}))).toThrow('原对象');expect(s.resources.goals.find(r=>r.id==='G-bound').activeBaseline.definition.owner).toBe(p.name);expect(()=>humanChangeOn(s,ci(s,p,{action:'complete',id,revision:c.revision}))).toThrow();});
